import { Quaternion, Vector3 } from 'three';

/**
 * Small deterministic rigid-body engine: boxes, spheres, an infinite ground plane,
 * sequential-impulse contact solver with Coulomb friction, and body sleeping.
 */

export type Shape = 'box' | 'sphere' | 'plane';

export class Body {
  readonly pos = new Vector3();
  readonly q = new Quaternion();
  readonly qInv = new Quaternion();
  readonly v = new Vector3();
  readonly w = new Vector3();
  readonly half = new Vector3();
  radius = 0;
  boundR = 0;
  invMass = 0;
  readonly invInertia = new Vector3();
  mu = 0.5;
  linDamp = 0.02;
  angDamp = 0.05;
  asleep = false;
  locked = false;
  sleepTimer = 0;
  /** effective inverse mass for the current step (0 for static / sleeping) */
  inv = 0;

  readonly initPos = new Vector3();
  readonly initQ = new Quaternion();
  initAsleep = false;
  initLocked = false;

  constructor(readonly shape: Shape, readonly isStatic: boolean) {}

  static box(size: Vector3, mass: number, pos: Vector3, q: Quaternion, isStatic: boolean): Body {
    const b = new Body('box', isStatic);
    b.half.set(size.x / 2, size.y / 2, size.z / 2);
    b.boundR = b.half.length();
    b.pos.copy(pos);
    b.q.copy(q);
    if (!isStatic) {
      b.invMass = 1 / mass;
      const k = mass / 12;
      b.invInertia.set(
        1 / (k * (size.y * size.y + size.z * size.z)),
        1 / (k * (size.x * size.x + size.z * size.z)),
        1 / (k * (size.x * size.x + size.y * size.y)),
      );
    }
    b.saveInitial();
    return b;
  }

  static sphere(radius: number, mass: number, pos: Vector3): Body {
    const b = new Body('sphere', false);
    b.radius = radius;
    b.boundR = radius;
    b.pos.copy(pos);
    b.invMass = 1 / mass;
    const i = 1 / ((2 / 5) * mass * radius * radius);
    b.invInertia.set(i, i, i);
    b.saveInitial();
    return b;
  }

  static plane(): Body {
    return new Body('plane', true);
  }

  saveInitial(): void {
    this.initPos.copy(this.pos);
    this.initQ.copy(this.q);
    this.initAsleep = this.asleep;
    this.initLocked = this.locked;
  }

  reset(): void {
    this.pos.copy(this.initPos);
    this.q.copy(this.initQ);
    this.v.set(0, 0, 0);
    this.w.set(0, 0, 0);
    this.asleep = this.initAsleep;
    this.locked = this.initLocked;
    this.sleepTimer = 0;
  }

  wake(): void {
    this.asleep = false;
    this.sleepTimer = 0;
  }
}

interface Contact {
  a: Body;
  b: Body;
  n: Vector3; // from a to b
  p: Vector3;
  depth: number;
  ra: Vector3;
  rb: Vector3;
  t1: Vector3;
  t2: Vector3;
  mn: number;
  mt1: number;
  mt2: number;
  accN: number;
  accT1: number;
  accT2: number;
  mu: number;
  bias: number;
}

const GRAVITY = 9.81;
const MARGIN = 0.003;
const SLOP = 0.004;
const BAUMGARTE = 0.2;
const MAX_BIAS = 1.5;
const ITERATIONS = 16;
const WAKE_SPEED = 0.15;
const SLEEP_LIN = 0.03;
const SLEEP_ANG = 0.08;
const SLEEP_TIME = 0.5;

const tmpA = new Vector3();
const tmpB = new Vector3();
const tmpC = new Vector3();
const tmpD = new Vector3();
const tmpQ = new Quaternion();

function applyInvI(b: Body, t: Vector3, out: Vector3): Vector3 {
  out.copy(t).applyQuaternion(b.qInv);
  out.set(out.x * b.invInertia.x, out.y * b.invInertia.y, out.z * b.invInertia.z);
  return out.applyQuaternion(b.q);
}

function speedMeasure(b: Body): number {
  return b.v.length() + 0.5 * b.w.length();
}

export class World {
  readonly bodies: Body[] = [];
  readonly ground = Body.plane();
  private contacts: Contact[] = [];

  add(b: Body): Body {
    this.bodies.push(b);
    return b;
  }

  reset(): void {
    for (const b of this.bodies) b.reset();
  }

  step(dt: number): void {
    const bodies = this.bodies;
    for (const b of bodies) b.qInv.copy(b.q).invert();

    this.contacts = [];
    this.generateContacts();

    for (const b of bodies) b.inv = b.isStatic || b.asleep ? 0 : b.invMass;

    for (const b of bodies) {
      if (b.inv > 0) b.v.y -= GRAVITY * dt;
    }

    for (const c of this.contacts) this.preStep(c, dt);
    for (let it = 0; it < ITERATIONS; it++) {
      for (const c of this.contacts) this.solve(c);
    }

    for (const b of bodies) {
      if (b.inv === 0) continue;
      const ld = 1 / (1 + b.linDamp * dt);
      const ad = 1 / (1 + b.angDamp * dt);
      b.v.multiplyScalar(ld);
      b.w.multiplyScalar(ad);
      b.pos.addScaledVector(b.v, dt);
      tmpQ.set(b.w.x, b.w.y, b.w.z, 0).multiply(b.q);
      b.q.set(
        b.q.x + 0.5 * dt * tmpQ.x,
        b.q.y + 0.5 * dt * tmpQ.y,
        b.q.z + 0.5 * dt * tmpQ.z,
        b.q.w + 0.5 * dt * tmpQ.w,
      ).normalize();

      if (!b.locked) {
        if (b.v.length() < SLEEP_LIN && b.w.length() < SLEEP_ANG) {
          b.sleepTimer += dt;
          if (b.sleepTimer > SLEEP_TIME) {
            b.asleep = true;
            b.v.set(0, 0, 0);
            b.w.set(0, 0, 0);
          }
        } else {
          b.sleepTimer = 0;
        }
      }
    }
  }

  // ---------------------------------------------------------------- contacts

  private addContact(a: Body, b: Body, n: Vector3, p: Vector3, depth: number): void {
    this.contacts.push({
      a,
      b,
      n,
      p,
      depth,
      ra: new Vector3(),
      rb: new Vector3(),
      t1: new Vector3(),
      t2: new Vector3(),
      mn: 0,
      mt1: 0,
      mt2: 0,
      accN: 0,
      accT1: 0,
      accT2: 0,
      mu: Math.sqrt(a.mu * b.mu),
      bias: 0,
    });
  }

  private generateContacts(): void {
    const bodies = this.bodies;
    const ground = this.ground;
    ground.mu = 0.6;

    for (const b of bodies) {
      if (b.isStatic || b.asleep) continue;
      if (b.shape === 'sphere') {
        const depth = b.radius - b.pos.y;
        if (depth > -MARGIN) {
          this.addContact(ground, b, new Vector3(0, 1, 0), new Vector3(b.pos.x, 0, b.pos.z), depth);
        }
      } else if (b.shape === 'box') {
        for (let i = 0; i < 8; i++) {
          this.corner(b, i, tmpA);
          if (tmpA.y < MARGIN) {
            this.addContact(ground, b, new Vector3(0, 1, 0), tmpA.clone(), -tmpA.y);
          }
        }
      }
    }

    for (let i = 0; i < bodies.length; i++) {
      const A = bodies[i];
      for (let j = i + 1; j < bodies.length; j++) {
        const B = bodies[j];
        if (A.isStatic && B.isStatic) continue;
        const lim = A.boundR + B.boundR + 0.05;
        if (A.pos.distanceToSquared(B.pos) > lim * lim) continue;

        // wake sleeping bodies that are touched by a moving one
        if (A.asleep && !A.locked && !B.isStatic && !B.asleep && speedMeasure(B) > WAKE_SPEED) A.wake();
        if (B.asleep && !B.locked && !A.isStatic && !A.asleep && speedMeasure(A) > WAKE_SPEED) B.wake();

        const aDyn = !A.isStatic && !A.asleep;
        const bDyn = !B.isStatic && !B.asleep;
        if (!aDyn && !bDyn) continue;

        if (A.shape === 'box' && B.shape === 'box') {
          this.boxCorners(A, B);
          this.boxCorners(B, A);
        } else if (A.shape === 'box' && B.shape === 'sphere') {
          this.sphereBox(B, A);
        } else if (A.shape === 'sphere' && B.shape === 'box') {
          this.sphereBox(A, B);
        }
      }
    }
  }

  private corner(b: Body, i: number, out: Vector3): Vector3 {
    out.set(
      i & 1 ? b.half.x : -b.half.x,
      i & 2 ? b.half.y : -b.half.y,
      i & 4 ? b.half.z : -b.half.z,
    );
    return out.applyQuaternion(b.q).add(b.pos);
  }

  /** corners of `src` that lie inside `dst`; contact normal points from dst to src */
  private boxCorners(src: Body, dst: Body): void {
    const h = dst.half;
    for (let i = 0; i < 8; i++) {
      this.corner(src, i, tmpA);
      tmpB.copy(tmpA).sub(dst.pos).applyQuaternion(dst.qInv);
      const px = h.x + MARGIN - Math.abs(tmpB.x);
      const py = h.y + MARGIN - Math.abs(tmpB.y);
      const pz = h.z + MARGIN - Math.abs(tmpB.z);
      if (px <= 0 || py <= 0 || pz <= 0) continue;
      const n = new Vector3();
      let depth: number;
      if (px <= py && px <= pz) {
        n.set(Math.sign(tmpB.x) || 1, 0, 0);
        depth = px;
      } else if (py <= pz) {
        n.set(0, Math.sign(tmpB.y) || 1, 0);
        depth = py;
      } else {
        n.set(0, 0, Math.sign(tmpB.z) || 1);
        depth = pz;
      }
      n.applyQuaternion(dst.q);
      this.addContact(dst, src, n, tmpA.clone(), depth);
    }
  }

  private sphereBox(s: Body, box: Body): void {
    const h = box.half;
    const l = tmpB.copy(s.pos).sub(box.pos).applyQuaternion(box.qInv);
    const c = tmpC.set(
      Math.max(-h.x, Math.min(h.x, l.x)),
      Math.max(-h.y, Math.min(h.y, l.y)),
      Math.max(-h.z, Math.min(h.z, l.z)),
    );
    const diff = tmpD.copy(l).sub(c);
    const dist = diff.length();
    if (dist > s.radius + MARGIN) return;
    const n = new Vector3();
    let depth: number;
    if (dist > 1e-8) {
      n.copy(diff).divideScalar(dist);
      depth = s.radius - dist;
    } else {
      const dx = h.x - Math.abs(l.x);
      const dy = h.y - Math.abs(l.y);
      const dz = h.z - Math.abs(l.z);
      if (dx <= dy && dx <= dz) {
        n.set(Math.sign(l.x) || 1, 0, 0);
        c.x = n.x * h.x;
        depth = s.radius + dx;
      } else if (dy <= dz) {
        n.set(0, Math.sign(l.y) || 1, 0);
        c.y = n.y * h.y;
        depth = s.radius + dy;
      } else {
        n.set(0, 0, Math.sign(l.z) || 1);
        c.z = n.z * h.z;
        depth = s.radius + dz;
      }
    }
    n.applyQuaternion(box.q);
    const p = c.clone().applyQuaternion(box.q).add(box.pos);
    this.addContact(box, s, n, p, depth);
  }

  // ------------------------------------------------------------------ solver

  private effMass(c: Contact, dir: Vector3): number {
    let k = c.a.inv + c.b.inv;
    if (c.a.inv > 0) {
      tmpA.crossVectors(c.ra, dir);
      applyInvI(c.a, tmpA, tmpB);
      k += tmpC.crossVectors(tmpB, c.ra).dot(dir);
    }
    if (c.b.inv > 0) {
      tmpA.crossVectors(c.rb, dir);
      applyInvI(c.b, tmpA, tmpB);
      k += tmpC.crossVectors(tmpB, c.rb).dot(dir);
    }
    return k > 1e-12 ? 1 / k : 0;
  }

  private relVel(c: Contact, out: Vector3): Vector3 {
    out.crossVectors(c.b.w, c.rb).add(c.b.v);
    tmpD.crossVectors(c.a.w, c.ra).add(c.a.v);
    return out.sub(tmpD);
  }

  private preStep(c: Contact, dt: number): void {
    c.ra.copy(c.p).sub(c.a.pos);
    c.rb.copy(c.p).sub(c.b.pos);
    const n = c.n;
    if (Math.abs(n.x) > 0.57) c.t1.set(0, 1, 0).cross(n);
    else c.t1.set(1, 0, 0).cross(n);
    c.t1.normalize();
    c.t2.crossVectors(n, c.t1).normalize();
    c.mn = this.effMass(c, n);
    c.mt1 = this.effMass(c, c.t1);
    c.mt2 = this.effMass(c, c.t2);
    c.bias = Math.min((BAUMGARTE / dt) * Math.max(c.depth - SLOP, 0), MAX_BIAS);
  }

  private impulse(c: Contact, P: Vector3): void {
    const a = c.a;
    const b = c.b;
    if (b.inv > 0) {
      b.v.addScaledVector(P, b.inv);
      tmpA.crossVectors(c.rb, P);
      b.w.add(applyInvI(b, tmpA, tmpB));
    }
    if (a.inv > 0) {
      a.v.addScaledVector(P, -a.inv);
      tmpA.crossVectors(c.ra, P);
      a.w.sub(applyInvI(a, tmpA, tmpB));
    }
  }

  private solve(c: Contact): void {
    const rv = new Vector3();
    const P = new Vector3();

    // normal
    this.relVel(c, rv);
    const vn = rv.dot(c.n);
    let lambda = (-vn + c.bias) * c.mn;
    const old = c.accN;
    c.accN = Math.max(old + lambda, 0);
    lambda = c.accN - old;
    this.impulse(c, P.copy(c.n).multiplyScalar(lambda));

    // friction
    const maxF = c.mu * c.accN;
    this.relVel(c, rv);
    let l1 = -rv.dot(c.t1) * c.mt1;
    const o1 = c.accT1;
    c.accT1 = Math.max(-maxF, Math.min(maxF, o1 + l1));
    l1 = c.accT1 - o1;
    this.impulse(c, P.copy(c.t1).multiplyScalar(l1));

    this.relVel(c, rv);
    let l2 = -rv.dot(c.t2) * c.mt2;
    const o2 = c.accT2;
    c.accT2 = Math.max(-maxF, Math.min(maxF, o2 + l2));
    l2 = c.accT2 - o2;
    this.impulse(c, P.copy(c.t2).multiplyScalar(l2));
  }
}

import * as THREE from 'three';
import { Body, World } from './physics';

declare global {
  interface Window {
    __TASK_STATE__: {
      readonly phase: 'ready' | 'running' | 'settled';
      readonly total: number;
      readonly toppled: number;
      readonly ballReleased: boolean;
    };
    __EVAL_READY__?: boolean;
  }
}

// ------------------------------------------------------------------ constants
const TILE_COUNT = 30;
const TILE_SIZE = new THREE.Vector3(0.2, 1.0, 0.5); // thickness (along path), height, width
const TILE_SPACING = 0.6;
const TILE_MASS = 0.3;
const BALL_RADIUS = 0.35;
const BALL_MASS = 1.5;
const RAMP_LEN = 1.5;
const RAMP_THICK = 0.16;
const RAMP_WIDTH = 1.0;
const RAMP_ANGLE = (15 * Math.PI) / 180;
const RAMP_TO_FIRST = 1.4; // from ramp foot to first tile centre
const BALL_START_ON_RAMP = 1.2;
const DT = 1 / 240;
const MAX_FRAME = 0.1;
const TOPPLE_COS = Math.cos((60 * Math.PI) / 180);

// ------------------------------------------------------------------ layout
const AXIS_Y = new THREE.Vector3(0, 1, 0);
const AXIS_Z = new THREE.Vector3(0, 0, 1);

interface Placement {
  x: number;
  z: number;
  heading: number;
}

function buildPath(): Placement[] {
  const total = (TILE_COUNT - 1) * TILE_SPACING;
  const heading = (s: number) => 0.95 * Math.sin((2 * Math.PI * s) / total);
  const pts: Placement[] = [];
  let x = 0;
  let z = 0;
  for (let i = 0; i < TILE_COUNT; i++) {
    const s = i * TILE_SPACING;
    pts.push({ x, z, heading: heading(s) });
    const hm = heading(s + TILE_SPACING / 2);
    x += TILE_SPACING * Math.cos(hm);
    z += TILE_SPACING * Math.sin(hm);
  }
  return pts;
}

const path = buildPath();
// ramp occupies -x of first tile (first heading is 0)
const rampFootX = path[0].x - RAMP_TO_FIRST;
const rampTopX = rampFootX - RAMP_LEN * Math.cos(RAMP_ANGLE) - 0.3;
let minX = rampTopX;
let maxX = -Infinity;
let minZ = Infinity;
let maxZ = -Infinity;
for (const p of path) {
  maxX = Math.max(maxX, p.x + 0.3);
  minX = Math.min(minX, p.x - 0.3);
  minZ = Math.min(minZ, p.z - 0.4);
  maxZ = Math.max(maxZ, p.z + 0.4);
}
const offX = -(minX + maxX) / 2;
const offZ = -(minZ + maxZ) / 2;
for (const p of path) {
  p.x += offX;
  p.z += offZ;
}
const halfSpanX = (maxX - minX) / 2;

// ------------------------------------------------------------------ renderer
const canvas = document.getElementById('app') as HTMLCanvasElement;
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true });
renderer.setPixelRatio(1);
renderer.setSize(640, 360, false);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x1b2230);

const camera = new THREE.PerspectiveCamera(40, 640 / 360, 0.1, 100);
{
  const tanH = Math.tan(THREE.MathUtils.degToRad(20)) * (640 / 360);
  const dist = (halfSpanX + 1.2) / tanH;
  const dir = new THREE.Vector3(0, 0.78, 0.63).normalize();
  const target = new THREE.Vector3(0, 0, 0.2);
  camera.position.copy(target).addScaledVector(dir, dist);
  camera.lookAt(target);
}

// lights
scene.add(new THREE.HemisphereLight(0xcfe0ff, 0x4a3a2a, 0.7));
const key = new THREE.DirectionalLight(0xfff1dd, 2.4);
key.position.set(-6, 12, 7);
key.castShadow = true;
key.shadow.mapSize.set(2048, 2048);
key.shadow.camera.left = -13;
key.shadow.camera.right = 13;
key.shadow.camera.top = 9;
key.shadow.camera.bottom = -9;
key.shadow.camera.near = 1;
key.shadow.camera.far = 40;
key.shadow.bias = -0.0004;
key.shadow.normalBias = 0.02;
key.shadow.radius = 5;
scene.add(key);

// ------------------------------------------------------------------ materials
function woodTexture(): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = 512;
  c.height = 256;
  const g = c.getContext('2d') as CanvasRenderingContext2D;
  g.fillStyle = '#8a5d38';
  g.fillRect(0, 0, c.width, c.height);
  let seed = 7;
  const rnd = () => {
    seed = (seed * 16807) % 2147483647;
    return seed / 2147483647;
  };
  for (let i = 0; i < 90; i++) {
    const y = rnd() * c.height;
    g.strokeStyle = `rgba(${50 + rnd() * 40},${25 + rnd() * 25},10,${0.1 + rnd() * 0.18})`;
    g.lineWidth = 1 + rnd() * 3;
    g.beginPath();
    g.moveTo(0, y);
    g.bezierCurveTo(c.width * 0.3, y + rnd() * 10 - 5, c.width * 0.6, y + rnd() * 10 - 5, c.width, y + rnd() * 6 - 3);
    g.stroke();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(2, 1);
  return t;
}

const tableMat = new THREE.MeshStandardMaterial({ map: woodTexture(), roughness: 0.75, metalness: 0.0 });
const rampMat = new THREE.MeshStandardMaterial({ color: 0x3c6e91, roughness: 0.5, metalness: 0.1 });
const ballMat = new THREE.MeshStandardMaterial({ color: 0xc9ced6, roughness: 0.22, metalness: 0.9 });

// table (visual; physics uses the y = 0 plane)
const table = new THREE.Mesh(new THREE.BoxGeometry(30, 0.4, 16), tableMat);
table.position.y = -0.2;
table.receiveShadow = true;
scene.add(table);

// ------------------------------------------------------------------ physics bodies
const world = new World();

// ramp
const rampFoot = new THREE.Vector3(rampFootX + offX, 0, path[0].z);
const rampUp = new THREE.Vector3(-Math.cos(RAMP_ANGLE), Math.sin(RAMP_ANGLE), 0);
const rampNormal = new THREE.Vector3(Math.sin(RAMP_ANGLE), Math.cos(RAMP_ANGLE), 0);
const rampCenter = rampFoot
  .clone()
  .addScaledVector(rampUp, RAMP_LEN / 2)
  .addScaledVector(rampNormal, -RAMP_THICK / 2);
const rampQ = new THREE.Quaternion().setFromAxisAngle(AXIS_Z, Math.PI - RAMP_ANGLE);
const rampBody = Body.box(new THREE.Vector3(RAMP_LEN, RAMP_THICK, RAMP_WIDTH), 1, rampCenter, rampQ, true);
rampBody.mu = 0.6;
world.add(rampBody);

const rampMesh = new THREE.Mesh(new THREE.BoxGeometry(RAMP_LEN, RAMP_THICK, RAMP_WIDTH), rampMat);
rampMesh.position.copy(rampCenter);
rampMesh.quaternion.copy(rampQ);
rampMesh.castShadow = true;
rampMesh.receiveShadow = true;
scene.add(rampMesh);

// ramp support post under the high end
{
  const topPt = rampFoot.clone().addScaledVector(rampUp, RAMP_LEN - 0.15);
  const underY = topPt.y - RAMP_THICK / Math.cos(RAMP_ANGLE);
  const postH = Math.max(underY, 0.05);
  const post = new THREE.Mesh(new THREE.BoxGeometry(0.14, postH, RAMP_WIDTH * 0.8), rampMat);
  post.position.set(topPt.x, postH / 2, topPt.z);
  post.castShadow = true;
  post.receiveShadow = true;
  scene.add(post);
}

// ball
const ballStart = rampFoot
  .clone()
  .addScaledVector(rampUp, BALL_START_ON_RAMP)
  .addScaledVector(rampNormal, BALL_RADIUS + 0.001);
const ball = Body.sphere(BALL_RADIUS, BALL_MASS, ballStart);
ball.mu = 0.6;
ball.linDamp = 0.05;
ball.angDamp = 0.4;
ball.asleep = true;
ball.locked = true;
ball.saveInitial();
world.add(ball);

const ballMesh = new THREE.Mesh(new THREE.SphereGeometry(BALL_RADIUS, 32, 20), ballMat);
ballMesh.castShadow = true;
ballMesh.receiveShadow = true;
scene.add(ballMesh);

// tiles
const tiles: Body[] = [];
const tileMeshes: THREE.Mesh[] = [];
const tileGeom = new THREE.BoxGeometry(TILE_SIZE.x, TILE_SIZE.y, TILE_SIZE.z);
for (let i = 0; i < TILE_COUNT; i++) {
  const p = path[i];
  const q = new THREE.Quaternion().setFromAxisAngle(AXIS_Y, -p.heading);
  const pos = new THREE.Vector3(p.x, TILE_SIZE.y / 2, p.z);
  const body = Body.box(TILE_SIZE, TILE_MASS, pos, q, false);
  body.mu = 0.5;
  body.asleep = true;
  body.saveInitial();
  world.add(body);
  tiles.push(body);

  const color = new THREE.Color().setHSL((i / TILE_COUNT) * 0.8, 0.6, 0.62);
  const mesh = new THREE.Mesh(
    tileGeom,
    new THREE.MeshStandardMaterial({ color, roughness: 0.35, metalness: 0.0 }),
  );
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  scene.add(mesh);
  tileMeshes.push(mesh);
}

// ------------------------------------------------------------------ state
let ballReleased = false;
let phase: 'ready' | 'running' | 'settled' = 'ready';
let toppled = 0;
let tilesTouched = false;
let simTimeSinceRelease = 0;

const internal = { phase, total: TILE_COUNT, toppled, ballReleased };
const publicState = {} as Window['__TASK_STATE__'];
Object.defineProperties(publicState, {
  phase: { get: () => internal.phase, enumerable: true },
  total: { get: () => internal.total, enumerable: true },
  toppled: { get: () => internal.toppled, enumerable: true },
  ballReleased: { get: () => internal.ballReleased, enumerable: true },
});
Object.defineProperty(window, '__TASK_STATE__', { value: publicState, writable: false, configurable: false });

// ------------------------------------------------------------------ UI
const ui = document.createElement('div');
ui.style.cssText =
  'position:absolute;left:10px;top:318px;display:flex;gap:8px;align-items:center;z-index:10;';
function makeButton(label: string): HTMLButtonElement {
  const b = document.createElement('button');
  b.textContent = label;
  b.style.cssText =
    'font:600 13px system-ui,sans-serif;padding:6px 14px;border:0;border-radius:5px;background:#f2c14e;color:#222;cursor:pointer;';
  return b;
}
const releaseBtn = makeButton('Release');
const resetBtn = makeButton('Reset');
resetBtn.style.background = '#d9dee7';
const label = document.createElement('span');
label.style.cssText = 'font:12px system-ui,sans-serif;color:#fff;text-shadow:0 1px 2px #000;margin-left:6px;';
ui.append(releaseBtn, resetBtn, label);
document.body.appendChild(ui);

function release(): void {
  if (ballReleased) return;
  ballReleased = true;
  phase = 'running';
  ball.locked = false;
  ball.wake();
}

function reset(): void {
  world.reset();
  ballReleased = false;
  phase = 'ready';
  tilesTouched = false;
  simTimeSinceRelease = 0;
  accumulator = 0;
  syncMeshes();
  updateState();
}

releaseBtn.addEventListener('click', release);
resetBtn.addEventListener('click', reset);

// ------------------------------------------------------------------ loop
function syncMeshes(): void {
  for (let i = 0; i < TILE_COUNT; i++) {
    tileMeshes[i].position.copy(tiles[i].pos);
    tileMeshes[i].quaternion.copy(tiles[i].q);
  }
  ballMesh.position.copy(ball.pos);
  ballMesh.quaternion.copy(ball.q);
}

const upTmp = new THREE.Vector3();
function updateState(): void {
  let count = 0;
  let allAsleep = true;
  for (const t of tiles) {
    upTmp.set(0, 1, 0).applyQuaternion(t.q);
    if (upTmp.y < TOPPLE_COS) count++;
    if (!t.asleep) allAsleep = false;
  }
  toppled = count;
  if (ballReleased) {
    if (!allAsleep) tilesTouched = true;
    if (phase === 'running' && ((tilesTouched && allAsleep) || simTimeSinceRelease > 60)) {
      phase = 'settled';
    }
  }
  internal.phase = phase;
  internal.toppled = toppled;
  internal.ballReleased = ballReleased;
  label.textContent = `Toppled ${toppled} / ${TILE_COUNT}`;
}

let accumulator = 0;
let last = performance.now();
let firstFrame = true;

function frame(now: number): void {
  const dt = Math.min((now - last) / 1000, MAX_FRAME);
  last = now;
  accumulator += dt;
  while (accumulator >= DT) {
    world.step(DT);
    accumulator -= DT;
    if (ballReleased && phase === 'running') simTimeSinceRelease += DT;
  }
  syncMeshes();
  updateState();
  renderer.render(scene, camera);
  if (firstFrame) {
    firstFrame = false;
    window.__EVAL_READY__ = true;
  }
  requestAnimationFrame(frame);
}

syncMeshes();
updateState();
requestAnimationFrame(frame);
